<template>
  <div class="row p-t-3 full-width justify-start">
    <!-- Classification Icon -->
    <div
      class="classify-content"
      :class="!isReadOnly && !hide_reclassify_btn ? 'col-1' : ''"
    >
      <labelClassificationBtn v-if="!isReadOnly && !hide_reclassify_btn" />
    </div>

    <!-- Doc type dropdown -->
    <div class="col-6">
      <docTypeDropdown :isReadOnly="isReadOnly" />
    </div>

    <!-- Amount & Date dropdown -->
    <div
      v-if="record.extraction_method != 'ELECTRONIC_DOCUMENT'"
      class="q-pl-sm"
      :class="!isReadOnly && !hide_reclassify_btn ? 'col-5' : 'col-6'"
    >
      <LanguageDropdown :isReadOnly="isReadOnly" />
    </div>
  </div>

  <!-- Dialog starts -->
  <q-dialog v-model="restart_classification_popup" persistent>
    <RestartClassificationPopup :isReadOnly="isReadOnly" />
  </q-dialog>
  <!--  dialog end -->

  <!-- Dialog starts -->
  <q-dialog v-model="label_classification_popup" persistent>
    <LabelClassificationPopup :isReadOnly="isReadOnly" />
  </q-dialog>
  <!-- dialog end -->

  <Classification />
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import Classification from 'src/components/Classification.vue';
import {
  useDocumentStore,
  useLangOriginDropdownStore,
  useDocClassificationStore,
} from 'src/store/main';
import RestartClassificationPopup from 'src/pages/FieldValidation/restartClassificationPopup.vue';
import LabelClassificationPopup from 'src/pages/FieldValidation/LabelClassificationPopup.vue';
import labelClassificationBtn from 'src/components/document/classification/label_classificationBtn.vue';
import docTypeDropdown from 'src/components/document/classification/doc_type_dropdown.vue';
import LanguageDropdown from 'src/components/document/classification/language_dropdown.vue';

export default defineComponent({
  name: 'DocumentClassification',

  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    hide_reclassify_btn: {
      type: Boolean,
      default: false,
    },
  },
  mixins: [],
  components: {
    Classification,
    RestartClassificationPopup,
    LabelClassificationPopup,
    labelClassificationBtn,
    docTypeDropdown,
    LanguageDropdown,
  },
  data() {
    return {};
  },
  mounted: function () {
    this.initPage();
  },

  methods: {
    async initPage() {
      await this.getLanguageIfEmpty();
    },
  },

  setup() {
    const classification_store = useDocClassificationStore();
    const { restart_classification_popup, label_classification_popup } =
      storeToRefs(classification_store);

    const language_origin_dropdown = useLangOriginDropdownStore();
    const { getLanguageIfEmpty } = language_origin_dropdown;

    const doc_store = useDocumentStore();
    const { selected_doc_type, record } = storeToRefs(doc_store);

    return {
      getLanguageIfEmpty,
      selected_doc_type,
      restart_classification_popup,
      label_classification_popup,
      record,
    };
  },
});
</script>

<style lang="css" scoped>
.classify-content {
  display: flex;
  justify-content: right;
}
</style>
