<template>
  <q-select
    outlined
    dense
    class="back-white"
    v-model="language_origin"
    :options="language_origin_list"
    emit-value
    map-options
    @update:model-value="restart_classification_popup = true"
    :disable="isReadOnly"
  >
    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps">
        <q-item-section>
          <q-item-label>{{ scope.opt.label }}</q-item-label>
          <q-tooltip v-if="scope.opt.description">
            <span v-html="scope.opt.description"></span
          ></q-tooltip>
        </q-item-section>
      </q-item>
    </template>

    <template v-slot:prepend>
      <q-icon flat dense color="primary">
        <Icon icon="mdi:web" width="20" height="20" class="black_to_white" />
      </q-icon>
    </template>
  </q-select>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';

import {
  useDocumentStore,
  useLangOriginDropdownStore,
  useDocClassificationStore,
} from 'src/store/main';

export default defineComponent({
  props: {
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  mixins: [],
  
  data() {
    return {};
  },
  methods: {},

  setup() {
    const classification_store = useDocClassificationStore();
    const { restart_classification_popup } = storeToRefs(classification_store);

    const doc_store = useDocumentStore();
    const { language_origin } = storeToRefs(doc_store);

    const language_origin_dropdown = useLangOriginDropdownStore();
    const { language_origins: language_origin_list } = storeToRefs(
      language_origin_dropdown,
    );

    return {
      restart_classification_popup,
      language_origin,
      language_origin_list,
    };
  },
});
</script>
